from ortools.sat.python import cp_model
import json

# Input data
n = 13  # Number of balls
c = 3   # Number of boxes

# Create the model
model = cp_model.CpModel()

# Decision variables: M[i][j] is True if ball i is in box j (0-based indices)
M = []
for i in range(n):
    boxes = []
    for j in range(c):
        boxes.append(model.NewBoolVar(f'M_{i}_{j}'))
    M.append(boxes)

# Each ball must be in exactly one box
for i in range(n):
    model.AddExactlyOne(M[i][j] for j in range(c))

# Generate all (x, y, z) triples where x + y = z, x <= y, and x, y, z <= n
triples = []
for z in range(2, n + 1):
    for x in range(1, z):
        y = z - x
        if x <= y and y <= n:
            triples.append((x, y, z))

# Add constraints for each triple and each box
for x, y, z in triples:
    for j in range(c):
        model.Add(M[x-1][j] + M[y-1][j] + M[z-1][j] <= 2)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # Extract the solution: balls[i] is the box (1-3) for ball i+1
    balls = []
    for i in range(n):
        for j in range(c):
            if solver.Value(M[i][j]):
                balls.append(j + 1)
                break
    solution = {'balls': balls}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
